SELECT * FROM customer limit 10;

-- Total Revenue generated by male vs female customers
SELECT gender, SUM(customer.purchase_amount) as revenue from customer
GROUP BY gender 


-- Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount 
FROM customer 
WHERE purchase_amount >=(SELECT AVG(purchase_amount) FROM customer) AND discount_applied = 'Yes';


--  which are the top 5 products with the highest average review rating?
SELECT item_purchased, ROUND(AVG(review_rating::numeric),2) as average_product_rating
FROM customer  
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;


--  Compare the average purchase amounts between standard and express shipping
SELECT shipping_type, ROUND(AVG(purchase_amount),2) as average_purchase_amount
FROM customer
WHERE shipping_type IN ('Standard','Express')
GROUP BY shipping_type
ORDER BY AVG(purchase_amount) DESC
;


--  DO subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

SELECT subscription_status, COUNT(customer_id), 
ROUND(AVG(purchase_amount),2) as average_spend, SUM(purchase_amount) as total_revenue
FROM customer
GROUP BY subscription_status
;


--  Which 5 products have the highest percentage of purchases with discounts applied?
SELECT item_purchased, 
ROUND(100 * SUM(CASE
		WHEN discount_applied = 'Yes' THEN 1
		ELSE 0
	END
)/COUNT(*),2) as discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5
;


-- segment customers into New, Returning, and Loyal based on their total number of previous purchases, 
-- and show the count of each segment

WITH customer_type AS (
SELECT customer_id, previous_purchases,	
	CASE 
		WHEN previous_purchases = 1 THEN 'New'
		WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
		ELSE 'Loyal'
	END AS customer_segment
FROM customer
)

SELECT customer_segment,COUNT(*) AS "Number of Customers" FROM customer_type
GROUP BY customer_segment 
;


